// ---
interface Execution {
  id: string;
  tipo: "executada" | "planejada";
  publico: string;
  solucao: string;
  mes: string;
  codSolucao: string;
  codFoco: string;
  codEvento: string;
}
interface MuniData {
  executions: Execution[];
  startupAtendida: boolean;
  eli: boolean;
  cidadeEmpreendedora: boolean;
}
type Territorios = Record<string, MuniData>;

// ---
const PUBLICOS = [
  { key: "gov", label: ".GOV", desc: "Prefeituras",  icon: Landmark,      color: "#3B6E5C" },
  { key: "edu", label: ".EDU", desc: "Educação",     icon: GraduationCap, color: "#B5562C" },
  { key: "com", label: ".COM", desc: "Empresas",     icon: Building2,     color: "#3A5A8C" },
];
const MESES = ["janeiro","fevereiro","março","abril","maio","junho",
               "julho","agosto","setembro","outubro","novembro","dezembro"];
const MUNICIPIOS_SE = (SE_GEO as {name:string}[])
  .map(f => f.name)
  .sort((a,b) => a.localeCompare(b,"pt-BR"));
const uid = () => Math.random().toString(36).slice(2,10) + Date.now().toString(36);

// ---
function computeStatus(data: MuniData) {
  // Migração automática: execuções antigas sem campo "tipo" tratadas como "executada"
  const exec = data.executions.filter(e => !e.tipo || e.tipo === "executada");
  const pubs = new Set(exec.map(e => e.publico));
  const ativado = pubs.size >= 2;
  const impulso = (ativado || data.eli) && data.startupAtendida;
  const planejadas = data.executions.filter(e => e.tipo === "planejada");
  const allPubs = new Set(data.executions.map(e => e.publico));
  const projetado = allPubs.size >= 2;
  return { ativado, impulso, qtdPublicos: pubs.size, planejadas: planejadas.length, executadas: exec.length, projetado };
}
function emptyMuni(): MuniData { return { executions: [], startupAtendida: false, eli: false, cidadeEmpreendedora: false }; }

// ---
function ringToPath(ring: number[][]): string {
  if (!ring || ring.length < 2) return "";
  return "M " + ring.map(([x,y]) => `${x},${y}`).join(" L ") + " Z";
}
function centroid(ring: number[][]): [number,number] {
  let cx=0, cy=0;
  for (const [x,y] of ring) { cx+=x; cy+=y; }
  return [cx/ring.length, cy/ring.length];
}
function getFill(data: MuniData, hov=false): string {
  const { ativado, impulso } = computeStatus(data);
  if (impulso)                    return hov ? "#FFD966" : "#F4C95D";
  if (ativado)                    return hov ? "#2A6B52" : "#1F4D3D";
  if (data.executions.filter(e=>!e.tipo||e.tipo==="executada").length > 0) return hov ? "#D9724A" : "#C8623A";
  if (data.executions.filter(e=>e.tipo==="planejada").length > 0) return hov ? "#8A7EB5" : "#7B6FA8";
  return hov ? "#BEB5A8" : "#C9C0B2";
}

// ---
interface MapaProps { territorios: Territorios; onSelect:(n:string)=>void; selected:string|null; }
function MapaSergipe({ territorios, onSelect, selected }: MapaProps) {
  const [tip, setTip]     = useState<{name:string;cx:number;cy:number}|null>(null);
  const [hov, setHov]     = useState<string|null>(null);
  const getMuni = (n:string): MuniData => territorios[n] || emptyMuni();
  const VW=560, VH=720;
  const sc = (r:number[][]): number[][] => r.map(([x,y])=>[x*VW/500, y*VH/700]);

  return (
    <div style={{background:"linear-gradient(160deg,#F7F3EC,#EEE8DC)",border:"1px solid #DDD5C4",borderRadius:20,padding:"20px 24px 18px",marginBottom:24,boxShadow:"0 2px 16px rgba(0,0,0,.06)"}}>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:16,flexWrap:"wrap",gap:10}}>
        <div>
          <span style={{fontWeight:700,fontSize:15,color:"#1A1612"}}>Mapa dos Territórios</span>
          <span style={{fontSize:13,color:"#9C9286",marginLeft:8}}>Sergipe · 75 municípios</span>
        </div>
        <div style={{display:"flex",gap:14,flexWrap:"wrap",fontSize:12.5,color:"#6B6259"}}>
          {([["#1F4D3D","Ativado",false],["#F4C95D","Conta p/ Impulso",true],["#C8623A","Em andamento",false],["#7B6FA8","Só planejado",false],["#C9C0B2","Sem ação",false]] as [string,string,boolean][]).map(([c,l,b])=>(
            <div key={l} style={{display:"flex",alignItems:"center",gap:5}}>
              <span style={{width:12,height:12,borderRadius:3,background:c,display:"inline-block",border:b?"2px solid #9A7B1E":"1px solid rgba(0,0,0,.12)",boxShadow:"0 1px 3px rgba(0,0,0,.1)"}}/>
              <span style={{fontWeight:500}}>{l}</span>
            </div>
          ))}
        </div>
      </div>
      <div style={{display:"flex",justifyContent:"center"}}>
        <svg viewBox={`0 0 ${VW} ${VH}`} style={{width:"100%",maxWidth:420,display:"block",borderRadius:14,border:"1px solid #C8DCE8",boxShadow:"inset 0 2px 8px rgba(0,0,0,.04),0 2px 12px rgba(0,0,0,.06)"}} onMouseLeave={()=>{setTip(null);setHov(null);}}>
          <defs>
            <linearGradient id="ocean" x1="0" y1="0" x2="1" y2="1">
              <stop offset="0%" stopColor="#C8E8F5"/>
              <stop offset="100%" stopColor="#A8D4EC"/>
            </linearGradient>
            <filter id="sh"><feDropShadow dx="0" dy="1" stdDeviation="1.2" floodColor="#00000022"/></filter>
            <filter id="glow"><feDropShadow dx="0" dy="0" stdDeviation="3" floodColor="#00000033"/></filter>
          </defs>
          <rect width={VW} height={VH} fill="url(#ocean)"/>
          <line x1={VW-20} y1={70} x2={VW-20} y2={VH-90} stroke="#7BBAD4" strokeWidth="2" strokeDasharray="5 4" opacity="0.6"/>
          {(SE_GEO as {name:string;rings:number[][][]}[]).map(({name,rings})=>{
            const data  = getMuni(name);
            const fill  = getFill(data, name===hov);
            const {impulso} = computeStatus(data);
            const isSel = name===selected;
            const isHov = name===hov;
            const [cx,cy] = centroid(rings[0]);
            return (
              <g key={name} style={{cursor:"pointer"}} filter={isHov||isSel?"url(#glow)":"url(#sh)"}
                onClick={()=>onSelect(name)}
                onMouseEnter={()=>{setTip({name,cx:cx*VW/500,cy:cy*VH/700});setHov(name);}}
                onMouseLeave={()=>{setTip(null);setHov(null);}}>
                {rings.map((r,i)=>(
                  <path key={i} d={ringToPath(sc(r))} fill={fill} stroke="#fff"
                    strokeWidth={isSel?"2.5":"0.9"} strokeLinejoin="round"/>
                ))}
                {impulso&&rings.map((r,i)=>(
                  <path key={"i"+i} d={ringToPath(sc(r))} fill="none" stroke="#C9A53C"
                    strokeWidth="2.5" strokeDasharray="5 3" strokeLinejoin="round" style={{pointerEvents:"none"}}/>
                ))}
                {isSel&&rings.map((r,i)=>(
                  <path key={"s"+i} d={ringToPath(sc(r))} fill="none" stroke="#fff"
                    strokeWidth="3.5" strokeLinejoin="round" style={{pointerEvents:"none"}}/>
                ))}
              </g>
            );
          })}
          {tip&&(()=>{
            const data=getMuni(tip.name);
            const {ativado,impulso,qtdPublicos,executadas,planejadas}=computeStatus(data);
            const fill=getFill(data);
            const status=impulso?"✦ Conta p/ Impulso":ativado?"✔ Ativado":qtdPublicos===1?"⚡ Em andamento":"○ Sem ação";
            const bw=192,bh=66;
            let bx=tip.cx+14,by=tip.cy-bh/2;
            if(bx+bw>VW-4)bx=tip.cx-bw-14;
            if(by<6)by=6;
            if(by+bh>VH-6)by=VH-bh-6;
            const words=tip.name.split(" ");
            const half=Math.ceil(words.length/2);
            const l1=words.slice(0,half).join(" "),l2=words.slice(half).join(" ");
            return (
              <g style={{pointerEvents:"none"}}>
                <rect x={bx+2} y={by+3} width={bw} height={bh} rx="9" fill="#00000033"/>
                <rect x={bx} y={by} width={bw} height={bh} rx="9" fill="#1A1612"/>
                <rect x={bx} y={by} width={4} height={bh} rx="9" fill={fill}/>
                <rect x={bx} y={by+4} width={4} height={bh-8} fill={fill}/>
                <text x={bx+14} y={by+17} fontSize="12" fontWeight="700" fill="#fff" fontFamily="Inter,sans-serif">{l1}</text>
                {l2&&<text x={bx+14} y={by+30} fontSize="12" fontWeight="700" fill="#fff" fontFamily="Inter,sans-serif">{l2}</text>}
                <rect x={bx+14} y={by+(l2?38:25)} width={9} height={9} rx="3" fill={fill}/>
                <text x={bx+27} y={by+(l2?47:34)} fontSize="10.5" fill="#C8C0B4" fontFamily="Inter,sans-serif">{status}</text>
                <text x={bx+14} y={by+bh-5} fontSize="9.5" fill="#888" fontFamily="Inter,sans-serif">{executadas} exec. · {planejadas} plan.</text>
                {data.eli&&<text x={bx+bw-32} y={by+(l2?47:34)} fontSize="9" fill="#B8A8E0" fontFamily="Inter,sans-serif" fontWeight="700">ELI</text>}
                {data.cidadeEmpreendedora&&<text x={bx+14} y={by+bh-4} fontSize="9" fill="#5B9BD5" fontFamily="Inter,sans-serif" fontWeight="700">🏙 Cidade Empreendedora</text>}
              </g>
            );
          })()}
        </svg>
      </div>
    </div>
  );
}

// ---
function CronogramaBar({ executions }: { executions: Execution[] }) {
  const porMes = MESES.map(mes => ({
    mes,
    exec: executions.filter(e => e.mes===mes && e.tipo==="executada"),
    plan: executions.filter(e => e.mes===mes && e.tipo==="planejada"),
  }));
  const maxTotal = Math.max(1, ...porMes.map(m => m.exec.length + m.plan.length));
  return (
    <div style={{marginBottom:14}}>
      <div style={{fontSize:12,fontWeight:700,color:"#857A6C",textTransform:"uppercase",letterSpacing:.5,marginBottom:8}}>Cronograma anual</div>
      <div style={{display:"flex",gap:3,alignItems:"flex-end",height:56}}>
        {porMes.map(({mes,exec,plan})=>{
          const total=exec.length+plan.length;
          const pct=total/maxTotal;
          return (
            <div key={mes} style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",gap:2}}>
              <div style={{width:"100%",display:"flex",flexDirection:"column",justifyContent:"flex-end",height:44,gap:1}}>
                {exec.length>0&&<div style={{background:"#1F4D3D",borderRadius:"2px 2px 0 0",height:`${(exec.length/maxTotal)*44}px`,minHeight:3,transition:"height .3s"}}/>}
                {plan.length>0&&<div style={{background:"#7B6FA8",borderRadius:exec.length===0?"2px 2px 0 0":"0",height:`${(plan.length/maxTotal)*44}px`,minHeight:3,border:"1px dashed #5C5080"}}/>}
              </div>
              <span style={{fontSize:8,color:"#B0A898",textAlign:"center",lineHeight:1}}>{mes.slice(0,3)}</span>
            </div>
          );
        })}
      </div>
      <div style={{display:"flex",gap:12,marginTop:6,fontSize:11,color:"#857A6C"}}>
        <span style={{display:"flex",alignItems:"center",gap:4}}><span style={{width:10,height:10,background:"#1F4D3D",borderRadius:2,display:"inline-block"}}/>Executada</span>
        <span style={{display:"flex",alignItems:"center",gap:4}}><span style={{width:10,height:10,background:"#7B6FA8",border:"1px dashed #5C5080",borderRadius:2,display:"inline-block"}}/>Planejada</span>
      </div>
    </div>
  );
}

